  "certified_type": {
    "category": "Non-automatic weighing instrument",
    "type_designations": ["SWII", "PRII", "PRII-B", "PRII-P", "PRII-U", "SWII-C", "SWII-E", "PRII-CB", "PRII-EB", "PRII-CP", "PRII-EP", "PRII-CU", "PRII-EU"],
